import { accessTokenForPersonalAccessKey as __accessTokenForPersonalAccessKey } from '@hubspot/local-dev-lib/personalAccessKey';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { PrivateAppUserTokenUnavailableError } from '../../serverless/errors.js';
import { executeFunction } from '../../serverless/executor.js';
import * as SecretsModule from '../../serverless/secrets.js';
import { PrivateAppUserTokenManager } from '../../serverless/services/PrivateAppUserTokenManager.js';
import { isTestOrSandboxAccount as __isTestOrSandboxAccount } from '../../utils.js';
import { NOOP_CALLBACK, TEST_CONFIG_V20251 as TEST_CONFIG, } from './fixtures/constants.js';
vi.mock('../../utils.ts', async () => {
    const actual = await vi.importActual('../../utils.ts');
    return {
        ...actual,
        isTestOrSandboxAccount: vi.fn(),
    };
});
vi.mock('@hubspot/local-dev-lib/personalAccessKey', () => ({
    accessTokenForPersonalAccessKey: vi.fn(),
}));
const isTestOrSandboxAccount = vi.mocked(__isTestOrSandboxAccount);
const accessTokenForPersonalAccessKey = vi.mocked(__accessTokenForPersonalAccessKey);
function makeTokenManager() {
    const manager = Object.create(PrivateAppUserTokenManager.prototype);
    manager.getPrivateAppUserToken = vi.fn();
    return manager;
}
describe('executor token gating', () => {
    const initialEnvJson = JSON.stringify(process.env);
    beforeEach(() => {
        isTestOrSandboxAccount.mockReset();
        accessTokenForPersonalAccessKey.mockReset();
        accessTokenForPersonalAccessKey.mockResolvedValue(undefined);
        // Prevent the v2025.1 fixture .env from supplying a PRIVATE_APP_ACCESS_TOKEN
        // so we can exercise the no-env-token branch.
        vi.spyOn(SecretsModule, 'loadSecrets').mockReturnValue({});
        delete process.env.PRIVATE_APP_ACCESS_TOKEN;
    });
    afterEach(() => {
        vi.resetAllMocks();
        process.env = JSON.parse(initialEnvJson);
    });
    it('skips getPrivateAppUserToken on test/sandbox accounts', async () => {
        isTestOrSandboxAccount.mockResolvedValue(true);
        const manager = makeTokenManager();
        let actual;
        await executeFunction(TEST_CONFIG, 'returns-text', { appId: 999 }, (value) => {
            actual = value;
        }, manager);
        expect(actual).toEqual('result');
        expect(manager.getPrivateAppUserToken).not.toHaveBeenCalled();
    });
    it('still calls getPrivateAppUserToken on standard accounts', async () => {
        isTestOrSandboxAccount.mockResolvedValue(false);
        const manager = makeTokenManager();
        manager.getPrivateAppUserToken.mockResolvedValue(undefined);
        await executeFunction(TEST_CONFIG, 'returns-text', { appId: 999 }, NOOP_CALLBACK, manager);
        expect(manager.getPrivateAppUserToken).toHaveBeenCalledTimes(1);
    });
    it('uses the config.yml access token when the account is sandbox/test and no env token is set', async () => {
        isTestOrSandboxAccount.mockResolvedValue(true);
        accessTokenForPersonalAccessKey.mockResolvedValue('pak-derived-token');
        const manager = makeTokenManager();
        let caught;
        await executeFunction(TEST_CONFIG, 'uses-secret', { appId: 999 }, NOOP_CALLBACK, manager).catch((err) => {
            caught = err;
        });
        expect(caught).not.toBeInstanceOf(PrivateAppUserTokenUnavailableError);
        expect(accessTokenForPersonalAccessKey).toHaveBeenCalledWith(TEST_CONFIG.accountId);
    });
    it('passes PrivateAppUserTokenUnavailableError through unwrapped when a function reads the secret on a test/sandbox account', async () => {
        isTestOrSandboxAccount.mockResolvedValue(true);
        const manager = makeTokenManager();
        let caught;
        try {
            await executeFunction(TEST_CONFIG, 'uses-secret', { appId: 999 }, NOOP_CALLBACK, manager);
        }
        catch (err) {
            caught = err;
        }
        expect(caught).toBeInstanceOf(PrivateAppUserTokenUnavailableError);
        const tokenErr = caught;
        expect(tokenErr.message).toContain(`accountId=${TEST_CONFIG.accountId}`);
        expect(tokenErr.hint).toContain('PRIVATE_APP_ACCESS_TOKEN');
    });
});
